mapper.update:
CREATE TABLE IF NOT EXISTS ${database}.${subTable}
USING ${database}.${superTable}
TAGS (#{deviceTag})

mapper.select:
SELECT
    ts,event_ts,device_name,point_id,point_code,rule_id,rule_name,alarm_level,alarm_event_type,message,value_text,value_double,value_long,value_bool,unit,payload_json,alarm_id,related_alarm_id,alarm_started_at,alarm_last_occurred_at,alarm_duration_ms
FROM ${database}.${subTable}
WHERE 1 = 1

    AND point_id = #{pointId}


    AND point_code = #{pointCode}


    AND alarm_level = #{alarmLevel}


    AND rule_id = #{ruleId}


    AND ts >= #{startTs}


    AND ts <= #{endTs}

ORDER BY ts DESC
LIMIT #{limit}

SELECT
    ts,event_ts,device_id,device_name,point_id,point_code,rule_id,rule_name,alarm_level,alarm_event_type,message,value_text,value_double,value_long,value_bool,unit,payload_json,alarm_id,related_alarm_id,alarm_started_at,alarm_last_occurred_at,alarm_duration_ms
FROM ${database}.${superTable}
WHERE 1 = 1

    AND device_id = #{deviceId}


    AND point_id = #{pointId}


    AND point_code = #{pointCode}


    AND alarm_level = #{alarmLevel}


    AND rule_id = #{ruleId}


    AND ts >= #{startTs}


    AND ts <= #{endTs}

ORDER BY ts DESC
LIMIT #{limit}

SELECT ts,event_ts,device_id,device_name,point_id,point_code,rule_id,rule_name,
       alarm_level,alarm_event_type,message,value_text,unit,payload_json,alarm_id,related_alarm_id,
       alarm_started_at,alarm_last_occurred_at,alarm_duration_ms
FROM ${database}.${superTable}
WHERE alarm_event_type = 'ALARM'
AND device_id = #{deviceId}
AND point_id = #{pointId}
AND point_code = #{pointCode}
AND rule_id = #{ruleId}
AND alarm_level = #{alarmLevel}
AND ts >= #{startTs}
AND ts <= #{endTs}
ORDER BY ts DESC
LIMIT #{limit} OFFSET #{offset}

SELECT related_alarm_id, alarm_id, alarm_event_type, event_ts, alarm_started_at, alarm_last_occurred_at, alarm_duration_ms, payload_json FROM ${database}.${superTable} WHERE related_alarm_id IN
#{alarmId}
AND alarm_event_type = 'ALARM_RECOVERED' ORDER BY ts DESC

SELECT COUNT(*)
FROM ${database}.${superTable}
WHERE 1 = 1

    AND device_id = #{deviceId}


    AND point_id = #{pointId}


    AND point_code = #{pointCode}


    AND alarm_level = #{alarmLevel}


    AND rule_id = #{ruleId}


    AND ts >= #{startTs}


    AND ts <= #{endTs}
